function evidence = f90_xbatt10_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XBATT10_EXTRACT_REFERENCE_EVIDENCE Replay the exact current reference.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end

expectedModelPresence = ...
    "present";
assert(isfile(modelPath), "SimuVerity:F90:XBATT10:ModelMissing", ...
    "Reference model is missing: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XBATT10:OfficialScenarios", ...
    "Official scenarios are missing: %s", officialScenarios);
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XBATT10:ReferenceAssetRoot", ...
    "Evaluator-owned reference asset root is missing: %s", evaluatorAssetRoot);
declaredPresence = lower(strtrim(string("present")));
assert(declaredPresence == expectedModelPresence && ...
    localFilePresence(modelPath) == expectedModelPresence, ...
    "SimuVerity:F90:XBATT10:ReferenceIdentity", ...
    "Reference file presence differs from the exact task binding.");

assetModelPath = fullfile(evaluatorAssetRoot, ...
    "Simulink Vehicle Model", "EV_Truck_Model.slx");
assetLicensePath = fullfile(evaluatorAssetRoot, "LICENSE");
assert(isfile(assetModelPath) && ...
    localFilePresence(assetModelPath) == expectedModelPresence && ...
    isfile(assetLicensePath) && localFilePresence(assetLicensePath) == ...
    "present", ...
    "SimuVerity:F90:XBATT10:ReferenceClosure", ...
    "The evaluator-owned XBATT-10 reference closure is incomplete or changed.");
official = localOfficialScenarios(officialScenarios);

assert(~isfolder(outputDir), "SimuVerity:F90:XBATT10:OutputReuse", ...
    "Reference evidence output directory already exists: %s", outputDir);
mkdir(outputDir);
runtimeRoot = string(tempname);
mkdir(runtimeRoot);
runtimeCleanup = onCleanup(@() localRemoveTree(runtimeRoot)); %#ok<NASGU>
cacheDir = fullfile(runtimeRoot, "cache");
codegenDir = fullfile(runtimeRoot, "codegen");
mkdir(cacheDir); mkdir(codegenDir);
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");

modelDir = string(fileparts(modelPath));
dataDir = fullfile(modelDir, "MATLAB Pre-defined Files");
assert(isfolder(dataDir), "SimuVerity:F90:XBATT10:ReferenceData", ...
    "The runtime reference data directory is missing.");
oldPath = path;
oldFolder = string(pwd);
stateCleanup = onCleanup(@() localRestore(oldPath, oldFolder)); %#ok<NASGU>
addpath(modelDir, dataDir, "-begin");
cd(modelDir);

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
scoringRunId = string(getenv("SIMUVERITY_SCORING_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XBATT10:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(strlength(scoringRunId) > 0, "SimuVerity:F90:XBATT10:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");

evidencePath = fullfile(outputDir, "evidence.json");
sourcePresenceBefore = localFilePresence(modelPath);
licensePresenceBefore = localFilePresence(assetLicensePath);
evidence = struct( ...
    "schema", "simuverity.f90-xbatt10-evidence.v1", ...
    "task_id", "F90-XBATT-10", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "reference_subject", true, ...
    "scoring_run_id", scoringRunId, ...
    "source_model", modelPath, ...
    "source_model_file_presence", sourcePresenceBefore, ...
    "core_source_modifications", 0, ...
    "runtime_input_overrides_only", true, ...
    "reference_substantive_modifications", 0, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "simulate_pass", false, ...
    "nominal_smoke_pass", false, ...
    "load_update_compile_simulate", false, ...
    "all_official_evidence_valid", false, ...
    "scenarios", struct([]), ...
    "structure", struct, ...
    "current_phase", "starting", ...
    "error_identifier", "", ...
    "error_message", "", ...
    "model_closed_without_save", false, ...
    "reference_binding_preserved", false, ...
    "license_binding_preserved", false, ...
    "runtime_model_unchanged", false, ...
    "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "scoring_run_id", scoringRunId, ...
        "matlab_release", string(version("-release")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "temp", string(getenv("TEMP")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));
localWriteJson(evidencePath, evidence);

model = "";
suiteStarted = tic;
try
    baseline = official.scenarios(1);
    localAssignBaseInputs(baseline);
    modelHandle = load_system(modelPath);
    model = string(get_param(modelHandle, "Name"));
    assert(model == "EV_Truck_Model", "SimuVerity:F90:XBATT10:ReferenceModelName", ...
        "Unexpected reference model name: %s", model);
    evidence.load_pass = true;
    set_param(model, "LimitDataPoints", "off", "StopTime", "12", ...
        "ReturnWorkspaceOutputs", "on");
    evidence.current_phase = "update";
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    localWriteJson(evidencePath, evidence);
    evidence.current_phase = "compile";
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    localWriteJson(evidencePath, evidence);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).profile = string(scenario.profile);
        rows(k).vehicle_mass_kg = double(scenario.vehicle_mass_kg);
        rows(k).powertrain_rating_kw = double(scenario.powertrain_rating_kw);
        rows(k).battery_initial_soc_fraction = ...
            double(scenario.battery_initial_soc_fraction);
        rows(k).regenerative_braking_enabled = ...
            double(scenario.regenerative_braking_enabled);
        evidence.current_phase = "simulate_" + string(scenario.id);
        try
            [profileTime, profileSpeed] = localProfile(string(scenario.profile));
            rows(k).profile_time_s = profileTime(:).';
            rows(k).profile_speed_mps = profileSpeed(:).';
            simIn = Simulink.SimulationInput(model);
            simIn = simIn.setVariable("Veh_mass", ...
                double(scenario.vehicle_mass_kg));
            simIn = simIn.setVariable("Power_option", ...
                double(scenario.powertrain_rating_kw));
            simIn = simIn.setVariable("Batt_soc_init", ...
                double(scenario.battery_initial_soc_fraction));
            simIn = simIn.setVariable("Elec_aux_sw", 1);
            simIn = simIn.setVariable("Elec_rgn_sw", ...
                double(scenario.regenerative_braking_enabled));
            simIn = simIn.setVariable("time", profileTime);
            simIn = simIn.setVariable("speed", profileSpeed);
            simIn = simIn.setModelParameter( ...
                "StopTime", "12", "ReturnWorkspaceOutputs", "on");
            started = tic;
            simOut = sim(simIn);
            elapsed = toc(started);
            rows(k) = localExtractScenario(rows(k), simOut, elapsed);
            clear simOut
        catch scenarioException
            rows(k).error_identifier = string(scenarioException.identifier);
            rows(k).error_message = string(scenarioException.message);
        end
        evidence.scenarios = rows;
        localWriteJson(evidencePath, evidence);
    end

    evidence.structure = struct( ...
        "battery_path_logged", true, ...
        "motor_path_logged", true, ...
        "vehicle_dynamics_logged", true, ...
        "closed_loop_commands_logged", true, ...
        "source_native_profile_interface_used", true, ...
        "source_native_design_inputs_used", true);
    evidence.simulate_pass = all([rows.valid]);
    evidence.nominal_smoke_pass = rows(1).valid;
    evidence.load_update_compile_simulate = evidence.load_pass && ...
        evidence.update_pass && evidence.compile_pass && evidence.simulate_pass;
    evidence.all_official_evidence_valid = evidence.simulate_pass;
    evidence.simulation_wall_clock_s = toc(suiteStarted);
    assert(evidence.simulate_pass, "SimuVerity:F90:XBATT10:ScenarioEvidence", ...
        "One or more fixed reference scenarios did not produce valid evidence.");

    localCloseModel(model);
    evidence.model_closed_without_save = ~bdIsLoaded(model);
    model = "";
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    evidence.license_binding_preserved = ...
        localFilePresence(assetLicensePath) == licensePresenceBefore;
    evidence.runtime_model_unchanged = evidence.reference_binding_preserved;
    evidence.current_phase = "complete";
    evidence.EVIDENCE_COMPLETE = evidence.load_update_compile_simulate && ...
        evidence.nominal_smoke_pass && evidence.all_official_evidence_valid && ...
        evidence.model_closed_without_save && ...
        evidence.reference_binding_preserved && evidence.license_binding_preserved;
    evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
    assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:F90:XBATT10:EvidenceIncomplete", ...
        "Reference extraction did not satisfy the evidence-lock prerequisites.");
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
catch sessionException
    try
        if strlength(model) > 0
            feval(model, [], [], [], "term");
        end
    catch
    end
    localCloseModel(model);
    evidence.model_closed_without_save = ...
        strlength(model) == 0 || ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    evidence.license_binding_preserved = ...
        localFilePresence(assetLicensePath) == licensePresenceBefore;
    evidence.runtime_model_unchanged = evidence.reference_binding_preserved;
    evidence.current_phase = "failed";
    evidence.error_identifier = string(sessionException.identifier);
    evidence.error_message = string(getReport( ...
        sessionException, "extended", "hyperlinks", "off"));
    evidence.EVIDENCE_COMPLETE = false;
    evidence.evidence_complete = false;
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
    rethrow(sessionException)
end

fprintf("F90_XBATT10_REFERENCE_EVIDENCE load=%d update=%d compile=%d valid=%d/%d complete=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    localValidCount(evidence.scenarios), numel(evidence.scenarios), ...
    evidence.EVIDENCE_COMPLETE, evidencePath);
end

function official = localOfficialScenarios(pathValue)
assert(localFilePresence(pathValue) == ...
    "present", ...
    "SimuVerity:F90:XBATT10:ScenarioIdentity", ...
    "Official scenario bytes differ from the current task contract.");
official = jsondecode(fileread(pathValue));
expectedIds = ["baseline", "heavy_mass", "low_soc", ...
    "low_power_heavy", "high_power_heavy", "regen_off"];
assert(isstruct(official) && string(official.schema) == ...
    "simuverity.official-scenarios.v1" && ...
    string(official.task_id) == "F90-XBATT-10" && ...
    isfield(official, "scenarios") && numel(official.scenarios) == 6 && ...
    isequal(string({official.scenarios.id}), expectedIds), ...
    "SimuVerity:F90:XBATT10:ScenarioContract", ...
    "Official scenario identity or ordering differs.");
end

function localAssignBaseInputs(scenario)
[profileTime, profileSpeed] = localProfile(string(scenario.profile));
assignin("base", "Veh_mass", double(scenario.vehicle_mass_kg));
assignin("base", "Power_option", double(scenario.powertrain_rating_kw));
assignin("base", "Batt_soc_init", ...
    double(scenario.battery_initial_soc_fraction));
assignin("base", "Elec_aux_sw", 1);
assignin("base", "Elec_rgn_sw", ...
    double(scenario.regenerative_braking_enabled));
assignin("base", "time", profileTime);
assignin("base", "speed", profileSpeed);
end

function [time, speed] = localProfile(profile)
if profile == "standard"
    time = [0; 1; 2; 4; 6; 8; 10; 12];
    speed = [0; 0; 4; 10; 10; 6; 0; 0];
elseif profile == "aggressive"
    time = [0; 1; 2; 3.5; 5.5; 7.5; 9.5; 12];
    speed = [0; 0; 7; 16; 16; 8; 0; 0];
else
    error("SimuVerity:F90:XBATT10:Profile", ...
        "Unknown fixed drive-cycle profile: %s", profile);
end
end

function row = localExtractScenario(row, simOut, elapsed)
dataset = simOut.get("logsout");
sampleTime = (0:0.1:12).';
drive = localSampleLog(dataset, "DriveCycle_Speed(km/h)", sampleTime);
vehicleSpeed = localSampleLog(dataset, "Vehicle_Speed(km/h)", sampleTime);
vehicleAcceleration = localSampleLog(dataset, ...
    "Vehicle_Acceleration(m/s^2)", sampleTime);
vehicleDistance = localSampleLog(dataset, "Vehicle_Distance(km)", sampleTime);
motorTorque = localSampleLog(dataset, "Motor_Torque(Nm)", sampleTime);
motorSpeed = localSampleLog(dataset, "Motor_Speed(RPM)", sampleTime);
motorPower = localSampleLog(dataset, "Motor_P_output(kW)", sampleTime);
batteryVoltage = localSampleLog(dataset, "Battery_Voltage(V)", sampleTime);
batteryCurrent = localSampleLog(dataset, "Battery_Current(A)", sampleTime);
batteryPower = localSampleLog(dataset, "Battery_P_output(kW)", sampleTime);
batterySoc = localSampleLog(dataset, "Battery_SOC(%)", sampleTime);
torqueCommand = localSampleLog(dataset, "VCU_TorqueCmd", sampleTime);
brakeCommand = localSampleLog(dataset, "VCU_BrakeCmd", sampleTime);
throttle = localSampleLog(dataset, "DriverInput_Throttle(0-100)", sampleTime);
brake = localSampleLog(dataset, "DriverInput_Brake(0-100)", sampleTime);

vehicle = localMakeLog(sampleTime, ...
    [drive vehicleSpeed vehicleAcceleration vehicleDistance], ...
    {'drive_cycle_speed_kph','vehicle_speed_kph', ...
     'vehicle_acceleration_mps2','vehicle_distance_km'}, ...
    {'km/h','km/h','m/s^2','km'});
motor = localMakeLog(sampleTime, [motorTorque motorSpeed motorPower], ...
    {'torque_Nm','speed_rpm','mechanical_power_kW'}, ...
    {'N*m','rpm','kW'});
battery = localMakeLog(sampleTime, ...
    [batteryVoltage batteryCurrent batteryPower batterySoc], ...
    {'voltage_V','current_A','power_kW','soc_fraction'}, ...
    {'V','A','kW','1'});
controls = localMakeLog(sampleTime, ...
    [torqueCommand brakeCommand throttle brake], ...
    {'torque_command_Nm','brake_command','throttle_percent','brake_percent'}, ...
    {'N*m','1','%','%'});
logs = struct("vehicle", vehicle, "motor", motor, ...
    "battery", battery, "controls", controls);

calculatedMotorPower = motorTorque .* motorSpeed .* (2*pi/60) ./ 1000;
powerScale = max(sqrt(mean(motorPower.^2)), 1e-9);
trackingError = vehicleSpeed - drive;
row.logs = logs;
row.simulate_s = elapsed;
row.valid = localLogsValid(logs);
row.metrics = struct( ...
    "tracking_rmse_kph", sqrt(mean(trackingError.^2)), ...
    "vehicle_speed_peak_kph", max(abs(vehicleSpeed)), ...
    "motor_torque_rms_Nm", sqrt(mean(motorTorque.^2)), ...
    "motor_power_abs_energy_kWh", trapz(sampleTime, abs(motorPower))/3600, ...
    "motor_power_negative_energy_kWh", ...
        trapz(sampleTime, max(-motorPower, 0))/3600, ...
    "motor_power_consistency_nrmse", ...
        sqrt(mean((motorPower-calculatedMotorPower).^2))/powerScale, ...
    "battery_voltage_mean_V", mean(batteryVoltage), ...
    "battery_current_rms_A", sqrt(mean(batteryCurrent.^2)), ...
    "battery_power_abs_energy_kWh", ...
        trapz(sampleTime, abs(batteryPower))/3600, ...
    "battery_power_negative_energy_kWh", ...
        trapz(sampleTime, max(-batteryPower, 0))/3600, ...
    "battery_soc_initial", batterySoc(1), ...
    "battery_soc_final", batterySoc(end), ...
    "battery_soc_delta", batterySoc(end)-batterySoc(1), ...
    "command_activity", max(abs(torqueCommand)) > 1 && ...
        (max(abs(throttle)) > 1 || max(abs(brake)) > 1));
end

function values = localSampleLog(dataset, name, sampleTime)
element = dataset.getElement(name);
assert(~isempty(element), "SimuVerity:F90:XBATT10:LogMissing", ...
    "Required source log is missing: %s", name);
time = double(element.Values.Time(:));
data = double(element.Values.Data(:));
[time, index] = unique(time, "stable");
data = data(index);
if numel(time) == 1
    values = repmat(data(1), numel(sampleTime), 1);
else
    values = interp1(time, data, sampleTime, "linear", "extrap");
end
values = values(:);
end

function value = localMakeLog(time, data, channels, units)
value = struct("time", time(:), "data", data, ...
    "channels", {channels}, "units", {units});
end

function valid = localLogsValid(logs)
names = fieldnames(logs);
valid = true;
for k = 1:numel(names)
    value = logs.(names{k});
    valid = valid && numel(value.time) == 121 && ...
        size(value.data, 1) == 121 && ...
        abs(value.time(1)) <= 1e-9 && ...
        abs(value.time(end) - 12) <= 1e-9 && ...
        all(diff(value.time) > 0) && all(isfinite(value.time)) && ...
        all(isfinite(value.data(:)));
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "profile", "", ...
    "vehicle_mass_kg", NaN, ...
    "powertrain_rating_kw", NaN, ...
    "battery_initial_soc_fraction", NaN, ...
    "regenerative_braking_enabled", NaN, ...
    "profile_time_s", [], ...
    "profile_speed_mps", [], ...
    "valid", false, ...
    "simulate_s", NaN, ...
    "logs", struct, ...
    "metrics", struct, ...
    "error_identifier", "", ...
    "error_message", "");
end

function localCloseModel(model)
try
    if strlength(model) > 0 && bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function localRestore(oldPath, oldFolder)
try, cd(oldFolder); catch, end
try, path(oldPath); catch, end
end

function localRemoveTree(pathValue)
try
    if isfolder(pathValue), rmdir(pathValue, "s"); end
catch
end
end

function count = localValidCount(rows)
if isempty(rows) || ~isfield(rows, "valid")
    count = 0;
else
    count = sum([rows.valid]);
end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w");
assert(fid > 0, "SimuVerity:F90:XBATT10:JsonWrite", ...
    "Could not open JSON output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
